#!/usr/bin/env python3
"""Starter analysis for a Jotter data folder.

Run it from inside the synced folder:

    python analyze.py
    python analyze.py --exercise "Bench Press"
    python analyze.py --weeks 26
    python analyze.py --food
    python analyze.py --sleep
    python analyze.py --stress

Requires pandas:  pip install pandas
"""
# jotter-docs v5 - regenerated by the app whenever it ships a newer copy.
import argparse
import datetime
import glob
import os
import sys

try:
    import pandas as pd
except ImportError:
    sys.exit("This script needs pandas:  pip install pandas")

HERE = os.path.dirname(os.path.abspath(__file__))

LB_PER_KG = 2.2046226218
MI_PER_KM = 0.621371192


def _read(pattern):
    """Concatenate every monthly file matching a glob pattern."""
    files = sorted(glob.glob(os.path.join(HERE, pattern)))
    # Skip sync-conflict copies so a conflicted folder does not double-count.
    files = [f for f in files if "conflict" not in os.path.basename(f).lower()]
    if not files:
        return pd.DataFrame()
    df = pd.concat([pd.read_csv(f) for f in files], ignore_index=True)
    df["date"] = pd.to_datetime(df["date"])
    return df.sort_values("date").reset_index(drop=True)


def load_sets():
    """All strength sets, normalised to kg, with e1RM and volume columns added."""
    df = _read("strength-*.csv")
    if df.empty:
        return df
    df["weight_kg"] = df["weight"].where(df.get("unit", "kg") != "lb", df["weight"] / LB_PER_KG)
    df["e1rm_kg"] = (df["weight_kg"] * (1 + df["reps"] / 30)).where(df["weight_kg"] > 0)
    df["volume_kg"] = df["weight_kg"] * df["reps"]
    return df


def load_cardio():
    """All cardio sessions, normalised to km and minutes."""
    df = _read("cardio-*.csv")
    if df.empty:
        return df
    df["distance_km"] = df["distance"].where(
        df.get("dist_unit", "km") != "mi", df["distance"] / MI_PER_KM
    )
    df["minutes"] = df["duration_sec"] / 60.0
    return df


SCALE_NAMES = {1: "healthy", 2: "everyday", 3: "indulgent"}


def load_food():
    """Every logged food/drink, with the scale named and an hour-of-day column."""
    df = _read("food-*.csv")
    if df.empty:
        return df
    if "qty" not in df.columns:
        df["qty"] = 1
    df["qty"] = df["qty"].fillna(1).astype(int)
    df["rating"] = df["scale"].map(SCALE_NAMES).fillna("everyday")
    # logged_at is when it was saved - close enough to when it was eaten to be useful.
    # It is UTC epoch millis, so convert to THIS machine's local time before taking the
    # hour; reading it as UTC silently shifts every "late night" entry by your offset.
    local_tz = datetime.datetime.now().astimezone().tzinfo
    stamps = pd.to_datetime(df["logged_at"], unit="ms", utc=True, errors="coerce")
    df["hour"] = stamps.dt.tz_convert(local_tz).dt.hour
    return df


def show_food(food, weeks):
    print("== Food ==")
    print("items logged   : %d" % food["qty"].sum())
    print("days logged    : %d" % food["date"].nunique())
    print("distinct items : %d" % food["item"].nunique())
    print("date range     : %s -> %s" % (food["date"].min().date(), food["date"].max().date()))
    print()

    print("-- most logged --")
    print(food.groupby("item")["qty"].sum().sort_values(ascending=False).head(20).to_string())
    print()

    print("-- by purpose --")
    print(food.groupby("purpose")["qty"].sum().sort_values(ascending=False).to_string())
    print()

    print("-- by rating --")
    mix = food.groupby("rating")["qty"].sum()
    total = mix.sum()
    for name, count in mix.sort_values(ascending=False).items():
        print("%-10s %5d  %4.1f%%" % (name, count, 100.0 * count / total))
    print()

    late = food[food["hour"] >= 21]["qty"].sum()
    if total:
        print("logged after 21:00 : %d (%.1f%%)" % (late, 100.0 * late / total))
    print()

    print("-- items per week, last %d weeks --" % weeks)
    print(food.set_index("date")["qty"].resample("W-MON").sum().tail(weeks).to_string())
    print()


SLEEP_QUALITY = {1: "poor", 2: "ok", 3: "good"}
STRESS_WEIGHT = {1: "minor", 2: "notable", 3: "major"}


def load_sleep():
    """Every logged night. date is the WAKE date, not the evening."""
    df = _read("sleep-*.csv")
    if df.empty:
        return df
    df["hours"] = df["duration_min"] / 60.0
    df["rating"] = df["quality"].map(SLEEP_QUALITY).fillna("ok")
    return df


def load_stress():
    df = _read("stress-*.csv")
    if df.empty:
        return df
    df["size"] = df["weight"].map(STRESS_WEIGHT).fillna("notable")
    return df


def show_sleep(sleep, weeks):
    print("== Sleep ==")
    span = (sleep["date"].max() - sleep["date"].min()).days + 1
    print("nights logged  : %d of %d in range" % (len(sleep), span))
    print("average        : %.2f h" % sleep["hours"].mean())
    print("under 6h       : %d nights" % (sleep["duration_min"] < 360).sum())
    print("shortest       : %.2f h   longest: %.2f h"
          % (sleep["hours"].min(), sleep["hours"].max()))
    print()
    print("-- quality mix --")
    mix = sleep.groupby("rating").size()
    for name, count in mix.sort_values(ascending=False).items():
        print("%-8s %4d  %4.1f%%" % (name, count, 100.0 * count / len(sleep)))
    print()
    print("-- average hours per week, last %d weeks --" % weeks)
    weekly = sleep.set_index("date")["hours"].resample("W-MON").mean()
    print(weekly.tail(weeks).round(2).to_string())
    print()


def show_stress(stress, weeks):
    print("== Stress ==")
    print("events logged  : %d" % len(stress))
    print("date range     : %s -> %s"
          % (stress["date"].min().date(), stress["date"].max().date()))
    print()
    for direction, title in (("BUSTER", "what you reached for"), ("ENHANCER", "what came up")):
        sel = stress[stress["direction"].str.upper() == direction]
        if sel.empty:
            continue
        print("-- %s --" % title)
        tally = sel.groupby("label").agg(
            events=("weight", "size"),
            major=("weight", lambda w: (w == 3).sum()),
            last=("date", "max"),
        ).sort_values("events", ascending=False)
        tally["last"] = tally["last"].dt.date
        print(tally.to_string())
        if direction == "BUSTER":
            print("on %d distinct days" % sel["date"].nunique())
        print()
    # Deliberately no enhancer:buster ratio - see README.md.


def show_exercise(sets, name):
    sel = sets[sets["exercise"].str.lower() == name.lower()]
    if sel.empty:
        known = ", ".join(sorted(sets["exercise"].unique()))
        sys.exit("No sets for %r.\nKnown exercises: %s" % (name, known))

    per_day = sel.groupby("date").agg(
        sets=("reps", "size"),
        total_reps=("reps", "sum"),
        top_weight_kg=("weight_kg", "max"),
        best_e1rm_kg=("e1rm_kg", "max"),
        volume_kg=("volume_kg", "sum"),
    )
    print("== %s ==" % sel["exercise"].iloc[-1])
    print(per_day.round(1).to_string())
    print()
    print("-- every set --")
    cols = ["date", "set_no", "reps", "weight", "unit", "bodyweight", "notes"]
    ordered = sel.sort_values(["date", "set_no"])
    print(ordered[[c for c in cols if c in ordered.columns]].to_string(index=False))


def show_summary(sets, cardio, food, sleep, stress, weeks):
    if not sets.empty:
        print("== Strength ==")
        print("sets logged    : %d" % len(sets))
        print("training days  : %d" % sets["date"].nunique())
        print("exercises used : %d" % sets["exercise"].nunique())
        print("date range     : %s -> %s" % (sets["date"].min().date(), sets["date"].max().date()))
        print()

        print("-- per exercise --")
        per_ex = sets.groupby("exercise").agg(
            sets=("reps", "size"),
            total_reps=("reps", "sum"),
            best_e1rm_kg=("e1rm_kg", "max"),
            last_done=("date", "max"),
        ).sort_values("sets", ascending=False)
        per_ex["last_done"] = per_ex["last_done"].dt.date
        print(per_ex.round(1).to_string())
        print()

        # pandas labels a W-MON bucket with the week's END date; the app's chart labels the
        # same bucket with its Monday start. Same numbers, dates shifted by six days.
        print("-- weekly tonnage (kg), week ending, last %d weeks --" % weeks)
        weekly = sets.set_index("date")["volume_kg"].resample("W-MON").sum()
        print(weekly.tail(weeks).round(0).to_string())
        print()

    if not cardio.empty:
        print("== Cardio ==")
        print("sessions       : %d" % len(cardio))
        print("total time     : %.1f h" % (cardio["minutes"].sum() / 60))
        print("total distance : %.1f km" % cardio["distance_km"].sum())
        print()
        print("-- per activity --")
        print(
            cardio.groupby("activity").agg(
                sessions=("minutes", "size"),
                minutes=("minutes", "sum"),
                km=("distance_km", "sum"),
            ).round(1).to_string()
        )
        print()
        print("-- weekly cardio minutes, week ending, last %d weeks --" % weeks)
        print(cardio.set_index("date")["minutes"].resample("W-MON").sum().tail(weeks).round(0).to_string())
        print()

    if not food.empty:
        show_food(food, weeks)

    if not sleep.empty:
        show_sleep(sleep, weeks)

    if not stress.empty:
        show_stress(stress, weeks)


def main():
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    ap.add_argument("--exercise", help="show the full history of one exercise")
    ap.add_argument("--weeks", type=int, default=12, help="how many weeks of trend to print")
    ap.add_argument("--food", action="store_true", help="show only the food log")
    ap.add_argument("--sleep", action="store_true", help="show only the sleep log")
    ap.add_argument("--stress", action="store_true", help="show only the stress log")
    args = ap.parse_args()

    sets = load_sets()
    cardio = load_cardio()
    food = load_food()
    sleep = load_sleep()
    stress = load_stress()

    if all(df.empty for df in (sets, cardio, food, sleep, stress)):
        sys.exit("No Jotter CSV files found in %s" % HERE)

    if args.food:
        if food.empty:
            sys.exit("No food data in this folder.")
        show_food(food, args.weeks)
    elif args.sleep:
        if sleep.empty:
            sys.exit("No sleep data in this folder.")
        show_sleep(sleep, args.weeks)
    elif args.stress:
        if stress.empty:
            sys.exit("No stress data in this folder.")
        show_stress(stress, args.weeks)
    elif args.exercise:
        if sets.empty:
            sys.exit("No strength data in this folder.")
        show_exercise(sets, args.exercise)
    else:
        show_summary(sets, cardio, food, sleep, stress, args.weeks)


if __name__ == "__main__":
    main()
